#!/bin/sh
# SSH connection from the console to the laptop (static Dropbear client, console key).
# Author: Patryk Strzelecki <patryk@strzelecki.info>
# Usage: ssh-laptop.sh               interactive PowerShell 7 on the laptop
#        ssh-laptop.sh menu          AI session menu (laptop\session-picker.ps1)
#        ssh-laptop.sh <command>     any remote command
# Settings: mustardos-remoteai.conf in this folder - generated by install.ps1 on the laptop from the
# main mustardos-remoteai.conf (only the keys the console needs, no passwords).
DIR="$(cd "$(dirname "$0")" && pwd)"
CONF="$DIR/mustardos-remoteai.conf"
# tr: tolerate CRLF if the file was edited on Windows
[ -f "$CONF" ] && eval "$(tr -d '\r' < "$CONF")"
LAPTOP_SSH_PORT="${LAPTOP_SSH_PORT:-22}"

fail() { echo "$1"; sleep 8; exit 1; }
[ -n "$LAPTOP_HOST" ] && [ -n "$LAPTOP_USER" ] || fail "LAPTOP_HOST / LAPTOP_USER not set in $CONF - run install.ps1 -Steps console on the laptop."

if [ "$1" = "menu" ]; then
    [ -n "$LAPTOP_APP_DIR" ] || fail "LAPTOP_APP_DIR is not set in $CONF - run install.ps1 -Steps console on the laptop."
    set -- "& '$LAPTOP_APP_DIR\\session-picker.ps1'"
fi

# HOME on the SD card -> known_hosts is kept in $DIR/.ssh/known_hosts
export HOME="$DIR" TERM=xterm-256color LANG=C.UTF-8
# -y: accept the laptop host key on first connect, verify it afterwards
"$DIR/dropbearmulti" dbclient -y -t -i "$DIR/id_ed25519" -K 30 -p "$LAPTOP_SSH_PORT" "$LAPTOP_USER@$LAPTOP_HOST" "$@"
RC=$?
if [ $RC -ne 0 ]; then
    echo "Cannot connect to the laptop ($LAPTOP_USER@$LAPTOP_HOST:$LAPTOP_SSH_PORT), exit code $RC."
    echo "Check: laptop is on, same Wi-Fi network, sshd service is running."
    sleep 6
fi
